#!/usr/bin/env bash
# ==============================================================================
# Local Project Verification Script
# Generated by Spring Boot Architecture Studio
# ==============================================================================
set -euo pipefail

BOLD="\033[1m"
GREEN="\033[0;32m"
RED="\033[0;31m"
YELLOW="\033[0;33m"
CYAN="\033[0;36m"
NC="\033[0m"

log_info()    { echo -e "${CYAN}[INFO]${NC} $1"; }
log_success() { echo -e "${GREEN}[✓]${NC} $1"; }
log_warn()    { echo -e "${YELLOW}[!]${NC} $1"; }
log_error()   { echo -e "${RED}[✗]${NC} $1"; }

echo -e "${BOLD}====================================================${NC}"
echo -e "${BOLD} Verifying Project: Demo (${CYAN}demo${NC})${BOLD}${NC}"
echo -e "${BOLD}====================================================${NC}"

# 1. Verify Java Environment
log_info "Checking Java environment..."
if ! command -v java >/dev/null 2>&1; then
    log_error "Java is not installed or not in PATH."
    echo "Please install JDK 21 or higher from https://adoptium.net/"
    exit 1
fi

JAVA_VER=$(java -version 2>&1 | awk -F[\"\.] '/version/ {print $2}')
if [ -z "$JAVA_VER" ]; then
    JAVA_VER=$(java -version 2>&1 | head -n 1 | grep -oE '[0-9]+' | head -n 1)
fi

REQ_JAVA=21
if [ "$JAVA_VER" -lt "$REQ_JAVA" ] 2>/dev/null; then
    log_warn "Detected Java $JAVA_VER, but this project is configured for JDK $REQ_JAVA+."
else
    log_success "Java $JAVA_VER detected (JDK $REQ_JAVA+ compatible)"
fi

# 2. Check Maven Wrapper
log_info "Checking Maven wrapper..."
if [ ! -f "./mvnw" ]; then
    log_error "./mvnw script not found in current directory."
    exit 1
fi
chmod +x ./mvnw
log_success "Maven wrapper ready"

# 4. Compile and Run Unit / Smoke Tests
log_info "Compiling project and running tests via Maven..."
if ./mvnw test; then
    log_success "All unit tests and code compilation passed!"
else
    log_error "Maven build / test failed. Check test reports in target/surefire-reports/"
    exit 1
fi

echo -e "${BOLD}====================================================${NC}"
echo -e "${GREEN}${BOLD}✓ PROJECT VERIFIED AND READY TO RUN${NC}"
echo -e "${BOLD}====================================================${NC}"
echo -e "To start the application, run:"
echo -e "  ${CYAN}./mvnw spring-boot:run${NC}"
echo -e "===================================================="
